const App = () => {
  const faqs = [
    {
      question: "Why do cats purr?",
      answer: "Cats purr for various reasons, including contentment, self-soothing when stressed or in pain, and even as a way to communicate with their kittens. The frequency of a cat's purr can also promote bone and tissue healing."
    },
    {
      question: "Why do cats have whiskers?",
      answer: "Whiskers are highly sensitive tactile organs that help cats navigate in the dark, detect subtle changes in air currents (to find prey), and determine if they can fit through narrow spaces."
    },
    {
      question: "Why do cats sleep so much?",
      answer: "Cats are crepuscular, meaning they are most active at dawn and dusk. They sleep an average of 12-16 hours a day to conserve energy for hunting, even if their 'hunting' just involves chasing a laser pointer."
    },
    {
      question: "Do cats always land on their feet?",
      answer: "Mostly, yes! Cats have a 'righting reflex' that allows them to twist their bodies mid-air. However, they still need enough height to complete the turn, and they can still be injured from falls."
    },
    {
      question: "Why do cats 'make biscuits' (knead)?",
      answer: "Kneading is a behavior carried over from kittenhood, where kittens knead their mother to stimulate milk flow. In adults, it's often a sign of comfort, security, and affection."
    }
  ];

  return (
    <div className="container">
      <header>
        <h1>Cat FAQ</h1>
        <p className="subtitle">Everything you ever wanted to know about your feline friends.</p>
      </header>
      <main className="faq-list">
        {faqs.map((faq, index) => (
          <FAQItem key={index} question={faq.question} answer={faq.answer} />
        ))}
      </main>
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
